CREATE TABLE IF NOT EXISTS public.hifz_sample_consents (user_id uuid PRIMARY KEY, consented_at timestamptz NOT NULL DEFAULT now(), adult_confirmed boolean NOT NULL DEFAULT false);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.hifz_sample_consents TO authenticated;
GRANT ALL ON public.hifz_sample_consents TO service_role;
ALTER TABLE public.hifz_sample_consents ENABLE ROW LEVEL SECURITY;
CREATE TABLE IF NOT EXISTS public.hifz_samples (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, path text NOT NULL UNIQUE, passages jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), note text NOT NULL DEFAULT '', consented_at timestamptz NOT NULL, sura integer, first_ayah integer, last_ayah integer, consent_at timestamptz, file_path text);
GRANT SELECT, INSERT, DELETE ON public.hifz_samples TO authenticated;
GRANT ALL ON public.hifz_samples TO service_role;
ALTER TABLE public.hifz_samples ENABLE ROW LEVEL SECURITY;
DO $$ BEGIN
IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='hifz_sample_consents' AND policyname='Own consent read') THEN CREATE POLICY "Own consent read" ON public.hifz_sample_consents FOR SELECT TO authenticated USING (user_id=auth.uid()); END IF;
IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='hifz_sample_consents' AND policyname='Own adult consent insert') THEN CREATE POLICY "Own adult consent insert" ON public.hifz_sample_consents FOR INSERT TO authenticated WITH CHECK (user_id=auth.uid() AND adult_confirmed); END IF;
IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='hifz_sample_consents' AND policyname='Own adult consent update') THEN CREATE POLICY "Own adult consent update" ON public.hifz_sample_consents FOR UPDATE TO authenticated USING (user_id=auth.uid()) WITH CHECK (user_id=auth.uid() AND adult_confirmed); END IF;
IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='hifz_sample_consents' AND policyname='Own consent delete') THEN CREATE POLICY "Own consent delete" ON public.hifz_sample_consents FOR DELETE TO authenticated USING (user_id=auth.uid()); END IF;
IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='hifz_samples' AND policyname='Own samples read for deletion') THEN CREATE POLICY "Own samples read for deletion" ON public.hifz_samples FOR SELECT TO authenticated USING (user_id=auth.uid()); END IF;
IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='hifz_samples' AND policyname='Own adult samples insert') THEN CREATE POLICY "Own adult samples insert" ON public.hifz_samples FOR INSERT TO authenticated WITH CHECK (user_id=auth.uid() AND split_part(path,'/',1)=auth.uid()::text AND char_length(note)<=200 AND EXISTS(SELECT 1 FROM public.hifz_sample_consents c WHERE c.user_id=auth.uid() AND c.adult_confirmed AND c.consented_at=hifz_samples.consented_at)); END IF;
IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='hifz_samples' AND policyname='Own samples delete') THEN CREATE POLICY "Own samples delete" ON public.hifz_samples FOR DELETE TO authenticated USING(user_id=auth.uid()); END IF;
IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='storage' AND tablename='objects' AND policyname='Adult sample upload') THEN CREATE POLICY "Adult sample upload" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='hifz-samples' AND (storage.foldername(name))[1]=auth.uid()::text AND EXISTS(SELECT 1 FROM public.hifz_sample_consents c WHERE c.user_id=auth.uid() AND c.adult_confirmed)); END IF;
IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='storage' AND tablename='objects' AND policyname='Own sample files read for deletion') THEN CREATE POLICY "Own sample files read for deletion" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='hifz-samples' AND (storage.foldername(name))[1]=auth.uid()::text); END IF;
IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='storage' AND tablename='objects' AND policyname='Own sample files delete') THEN CREATE POLICY "Own sample files delete" ON storage.objects FOR DELETE TO authenticated USING(bucket_id='hifz-samples' AND (storage.foldername(name))[1]=auth.uid()::text); END IF;
END $$;